'use strict';

// A detached flight still settles its original callers. The registry tracks
// only flights available for subsequent readers of each key.
function createFlights() {
  const pending = new Map();

  return {
    run(key, work, commit) {
      if (pending.has(key)) return pending.get(key);
      // Only the flight still registered for key may commit or unregister;
      // a detached flight must not store its value or evict a newer flight.
      const settle = () => {
        const current = pending.get(key) === promise;
        if (current) pending.delete(key);
        return current;
      };
      const promise = Promise.resolve().then(work).then(
        value => {
          if (settle()) commit(value);
          return value;
        },
        reason => {
          settle();
          throw reason;
        }
      );
      pending.set(key, promise);
      return promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

module.exports = { createFlights };

