'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
function d() { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; }

(async () => {
  // Old flight finishing after newer flight started must not evict/overwrite it.
  {
    const g = [d(), d(), d()]; let n = 0;
    const c = createCache({ now: () => 0, load: () => g[n++].promise });
    const a = c.get('k'); await tick();
    c.invalidate('k'); const b = c.get('k'); await tick();
    c.invalidate('k'); const cc = c.get('k'); await tick();
    g[0].resolve('A'); assert.equal(await a, 'A');
    assert.equal(c.size, 0);
    const join = c.get('k'); // must join flight 3, not start a 4th
    g[1].resolve('B'); assert.equal(await b, 'B'); assert.equal(c.size, 0);
    g[2].resolve('C'); assert.equal(await cc, 'C'); assert.equal(await join, 'C');
    assert.equal(n, 3); assert.equal(await c.get('k'), 'C'); assert.equal(n, 3);
  }
  // Rejection is not cached; all waiters share reason; retry works.
  {
    let n = 0; const reason = { not: 'error' };
    const c = createCache({ now: () => 0, load: () => { n++; if (n === 1) throw reason; return 'ok'; } });
    const [r1, r2] = await Promise.allSettled([c.get('k'), c.get('k')]);
    assert.equal(r1.reason, reason); assert.equal(r2.reason, reason); assert.equal(n, 1);
    assert.equal(await c.get('k'), 'ok'); assert.equal(n, 2);
  }
  // Detached rejection does not evict newer flight.
  {
    const g = [d(), d()]; let n = 0;
    const c = createCache({ now: () => 0, load: () => g[n++].promise });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick();
    g[0].reject(new Error('x')); await assert.rejects(a, /x/);
    const join = c.get('k'); g[1].resolve('B');
    assert.equal(await b, 'B'); assert.equal(await join, 'B'); assert.equal(n, 2);
  }
  // set wins; old completion doesn't restart TTL; expiry starts a new load.
  {
    let t = 0; const g = [d(), d()]; let n = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => g[n++].promise });
    const a = c.get('k'); await tick();
    c.set('k', 'S'); t = 5; g[0].resolve('old'); assert.equal(await a, 'old');
    assert.equal(await c.get('k'), 'S');
    t = 10; const nx = c.get('k'); assert.equal(n, 1); await tick(); assert.equal(n, 2);
    g[1].resolve('new'); assert.equal(await nx, 'new');
  }
  // load calling invalidate synchronously; clear detaches all.
  {
    let n = 0; const c = createCache({ now: () => 0, load: k => { n++; if (n === 1) c.invalidate(k); return 'v' + n; } });
    assert.equal(await c.get('k'), 'v1'); assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'v2'); assert.equal(c.size, 1);
    const g = d(); const c2 = createCache({ now: () => 0, load: () => g.promise });
    const p = c2.get('a'); await tick(); c2.clear(); g.resolve(1); await p; assert.equal(c2.size, 0);
  }
  // Load reading its own key joins its flight; TTL from commit; ttl 0.
  {
    let t = 0, n = 0, inner; const g = d();
    const c = createCache({ now: () => t, ttlMs: 10, load: k => { n++; inner = c.get(k); return g.promise; } });
    const p = c.get('k'); await tick(); t = 8; g.resolve('v');
    assert.equal(await p, 'v'); assert.equal(await inner, 'v'); assert.equal(n, 1);
    t = 17; assert.equal(c.size, 1); t = 18; assert.equal(c.size, 0);
    let m = 0; const z = createCache({ now: () => 0, ttlMs: 0, load: () => ++m });
    await Promise.all([z.get(1), z.get(1)]); assert.equal(m, 1); await z.get(1); assert.equal(m, 2);
  }
  console.log('scratch ok');
})().catch(e => { console.error(e); process.exit(1); });
